from __future__ import annotations
from math import fsum, log, prod
from typing import Sequence
Profile = Sequence[int]
def check(a: Profile) -> None:
    if any(type(x) is not int or x < 1 for x in a):
        raise ValueError("profiles require positive integers")
def count(a: Profile) -> int:
    check(a); return prod(a)
def volume(a: Profile) -> float:
    check(a); return fsum(log(x) for x in a)
def dimension(b: Profile, s: Profile) -> float:
    if len(b) != len(s) or any(y > x for x, y in zip(b, s)):
        raise ValueError("profiles must satisfy 1 <= s_i <= b_i")
    z = volume(b)
    if z == 0.0: raise ValueError("ambient volume is zero")
    return volume(s) / z

b = [2, 3, 5, 2]
s = [1, 2, 2, 2]
d = dimension(b, s)
print({"ambient_paths": count(b), "successful_paths": count(s), "dimension": d,
       "reconstructed_successful_paths": count(b) ** d})

