from dataclasses import dataclass
@dataclass(frozen=True)
class Result:
    ambient_count: int; successful_count: int
    ambient_volume: float; successful_volume: float; dimension: float
def analyze(b: Profile, s: Profile) -> Result:
    d = dimension(b, s)
    return Result(count(b), count(s), volume(b), volume(s), d)
