from typing import Iterable
def compose(phases: Iterable[tuple[Profile, Profile]]) -> float:
    numerator = denominator = 0.0
    for b, s in phases:
        w = volume(b); numerator += w * dimension(b, s); denominator += w
    if denominator == 0.0: raise ValueError("total ambient volume is zero")
    return numerator / denominator
if __name__ == "__main__": print(compose([([2],[2]), ([16],[2])]))

