from typing import Iterable
def rank_bottlenecks(phases: Iterable[tuple[str, Profile, Profile]]) -> list[tuple[str,float]]:
    scored = []
    for name, b, s in phases:
        dimension(b, s)  # validation
        scored.append((name, volume(b) - volume(s)))
    return sorted(scored, key=lambda item: item[1], reverse=True)
if __name__ == "__main__":
